import db from "../db.server";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ShopifyImageNode {
  url: string;
}

interface ShopifyPriceAmount {
  amount: string;
}

interface ShopifyPriceRange {
  minVariantPrice: ShopifyPriceAmount;
  maxVariantPrice: ShopifyPriceAmount;
}

interface ShopifyCollectionNode {
  id: string;
}

interface ShopifyProductNode {
  id: string;
  title: string;
  handle: string;
  tags: string[];
  status: string;
  featuredImage: ShopifyImageNode | null;
  priceRangeV2: ShopifyPriceRange;
  collections: {
    nodes: ShopifyCollectionNode[];
  };
}

interface ShopifyProductsData {
  products: {
    pageInfo: {
      hasNextPage: boolean;
      endCursor: string | null;
    };
    nodes: ShopifyProductNode[];
  };
}

interface ShopifySingleProductData {
  product: ShopifyProductNode | null;
}

// The graphql function signature as returned by authenticate.admin(request)
type AdminGraphql = (
  query: string,
  options?: { variables?: Record<string, unknown> }
) => Promise<Response>;

// ─── GraphQL Queries ──────────────────────────────────────────────────────────

const PRODUCTS_QUERY = `#graphql
  query GetProducts($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      pageInfo { hasNextPage endCursor }
      nodes {
        id
        title
        handle
        tags
        status
        featuredImage { url }
        priceRangeV2 {
          minVariantPrice { amount }
          maxVariantPrice { amount }
        }
        collections(first: 20) {
          nodes { id }
        }
      }
    }
  }
` as const;

const SINGLE_PRODUCT_QUERY = `#graphql
  query GetProduct($id: ID!) {
    product(id: $id) {
      id
      title
      handle
      tags
      status
      featuredImage { url }
      priceRangeV2 {
        minVariantPrice { amount }
        maxVariantPrice { amount }
      }
      collections(first: 20) {
        nodes { id }
      }
    }
  }
` as const;

// ─── Helpers ──────────────────────────────────────────────────────────────────

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase().replace(/\s+/g, "-");
}

function buildUpsertPayload(
  shop: string,
  product: ShopifyProductNode,
  isActive: boolean
) {
  const normalizedTags = product.tags.map(normalizeTag);
  const collectionGids = product.collections.nodes.map((c) => c.id);

  const create = {
    shop,
    productGid: product.id,
    title: product.title,
    handle: product.handle,
    imageUrl: product.featuredImage?.url ?? null,
    tags: JSON.stringify(normalizedTags),
    collections: JSON.stringify(collectionGids),
    priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
    priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
    status: isActive ? ("active" as const) : ("archived" as const),
    syncedAt: new Date(),
  };

  const update = {
    title: product.title,
    handle: product.handle,
    imageUrl: product.featuredImage?.url ?? null,
    tags: JSON.stringify(normalizedTags),
    collections: JSON.stringify(collectionGids),
    priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
    priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
    status: isActive ? ("active" as const) : ("archived" as const),
    syncedAt: new Date(),
  };

  return { create, update };
}

async function fetchProductsPage(
  admin: { graphql: AdminGraphql },
  cursor: string | null
): Promise<ShopifyProductsData["products"]> {
  const response = await admin.graphql(PRODUCTS_QUERY, {
    variables: { first: 50, after: cursor },
  });

  const json = (await response.json()) as { data: ShopifyProductsData };

  if (!json.data?.products) {
    throw new Error("Shopify GraphQL returned unexpected shape for products query");
  }

  return json.data.products;
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Full catalog sync. Paginates through all Shopify products (50 per page),
 * upserts active products, soft-deletes archived/draft ones, and then marks
 * any ProductMapping records NOT seen in this sync run as "archived"
 * (product was deleted from Shopify without a webhook firing).
 *
 * Returns { synced, archived } counts.
 */
export async function syncAllProducts(
  shop: string,
  admin: { graphql: AdminGraphql }
): Promise<{ synced: number; archived: number }> {
  let cursor: string | null = null;
  let hasMore = true;
  let synced = 0;
  let archivedDuringSync = 0;

  // Track every GID seen during this sync so we can archive any that went missing
  const seenGids = new Set<string>();

  while (hasMore) {
    let page: ShopifyProductsData["products"];

    try {
      page = await fetchProductsPage(admin, cursor);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Product sync failed while fetching page: ${message}`);
    }

    for (const product of page.nodes) {
      seenGids.add(product.id);
      const isActive = product.status === "ACTIVE";
      const { create, update } = buildUpsertPayload(shop, product, isActive);

      try {
        await db.productMapping.upsert({
          where: { shop_productGid: { shop, productGid: product.id } },
          create,
          update,
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.error(
          `[product-sync] Failed to upsert product ${product.id}: ${message}`
        );
        // Continue with remaining products — one bad record shouldn't abort the run
        continue;
      }

      if (isActive) {
        synced++;
      } else {
        archivedDuringSync++;
      }
    }

    hasMore = page.pageInfo.hasNextPage;
    cursor = page.pageInfo.endCursor;
  }

  // Soft-delete any ProductMapping records that were NOT seen in this sync.
  // These are products that were deleted from Shopify (no webhook fired, or we
  // missed it). Law 15: never hard-delete synced data.
  let ghostArchived = 0;
  if (seenGids.size > 0) {
    // Collect all active GIDs for this shop that were NOT in the sync
    const activeInDb = await db.productMapping.findMany({
      where: { shop, status: "active" },
      select: { productGid: true },
    });

    const missingGids = activeInDb
      .map((r) => r.productGid)
      .filter((gid) => !seenGids.has(gid));

    if (missingGids.length > 0) {
      const result = await db.productMapping.updateMany({
        where: { shop, productGid: { in: missingGids } },
        data: { status: "archived", syncedAt: new Date() },
      });
      ghostArchived = result.count;
    }
  } else if (seenGids.size === 0) {
    // If zero products came back, the store may be empty — archive everything
    // that was previously active rather than leaving stale records.
    const result = await db.productMapping.updateMany({
      where: { shop, status: "active" },
      data: { status: "archived", syncedAt: new Date() },
    });
    ghostArchived = result.count;
  }

  return {
    synced,
    archived: archivedDuringSync + ghostArchived,
  };
}

/**
 * Single-product sync, intended for webhook-triggered updates (PRODUCTS_CREATE
 * and PRODUCTS_UPDATE). Queries Shopify for the specific GID and upserts the
 * local record. If the product is not ACTIVE it is soft-deleted.
 */
export async function syncSingleProduct(
  shop: string,
  admin: { graphql: AdminGraphql },
  productGid: string
): Promise<void> {
  let response: Response;

  try {
    response = await admin.graphql(SINGLE_PRODUCT_QUERY, {
      variables: { id: productGid },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      `Failed to query Shopify for product ${productGid}: ${message}`
    );
  }

  const json = (await response.json()) as { data: ShopifySingleProductData };

  if (!json.data) {
    throw new Error(
      `Shopify GraphQL returned no data for product ${productGid}`
    );
  }

  const product = json.data.product;

  if (!product) {
    // Product was deleted from Shopify — soft-delete the local record if it exists
    await db.productMapping.updateMany({
      where: { shop, productGid },
      data: { status: "archived", syncedAt: new Date() },
    });
    return;
  }

  const isActive = product.status === "ACTIVE";
  const { create, update } = buildUpsertPayload(shop, product, isActive);

  await db.productMapping.upsert({
    where: { shop_productGid: { shop, productGid: product.id } },
    create,
    update,
  });
}

/**
 * Returns the count of active ProductMapping records for the shop.
 * Used by the admin UI to display "X products synced".
 */
export async function getProductCount(shop: string): Promise<number> {
  return db.productMapping.count({
    where: { shop, status: "active" },
  });
}

/**
 * Case-insensitive title search across active ProductMapping records.
 * Used by the admin product picker when building result pages.
 */
export async function searchProducts(
  shop: string,
  query: string,
  limit: number = 20
): Promise<
  Array<{
    productGid: string;
    title: string;
    imageUrl: string | null;
    handle: string | null;
  }>
> {
  const results = await db.productMapping.findMany({
    where: {
      shop,
      status: "active",
      title: { contains: query },
    },
    select: {
      productGid: true,
      title: true,
      imageUrl: true,
      handle: true,
    },
    orderBy: { title: "asc" },
    take: limit,
  });

  return results;
}

/**
 * Returns the most-recently-synced timestamp for the shop, or null if no sync
 * has been run yet. Used by the admin UI to show "Last synced X minutes ago".
 */
export async function getLastSyncedAt(shop: string): Promise<Date | null> {
  const latest = await db.productMapping.findFirst({
    where: { shop },
    orderBy: { syncedAt: "desc" },
    select: { syncedAt: true },
  });
  return latest?.syncedAt ?? null;
}

