 43→}
 44→
 45→interface ShopifySingleProductData {
 46→  product: ShopifyProductNode | null;
 47→}
 48→
 49→// The graphql function signature as returned by authenticate.admin(request)
 50→type AdminGraphql = (
 51→  query: string,
 52→  options?: { variables?: Record<string, unknown> }
 53→) => Promise<Response>;
 54→
 55→// ─── GraphQL Queries ──────────────────────────────────────────────────────────
 56→
 57→const PRODUCTS_QUERY = `#graphql
 58→  query GetProducts($first: Int!, $after: String) {
 59→    products(first: $first, after: $after) {
 60→      pageInfo { hasNextPage endCursor }
 61→      nodes {
 62→        id
 63→        title
 64→        handle
 65→        tags
 66→        status
 67→        featuredImage { url }
 68→        priceRangeV2 {
 69→          minVariantPrice { amount }
 70→          maxVariantPrice { amount }
 71→        }
 72→        collections(first: 20) {
 73→          nodes { id }
 74→        }
 75→      }
 76→    }
 77→  }
 78→` as const;
 79→
 80→const SINGLE_PRODUCT_QUERY = `#graphql
 81→  query GetProduct($id: ID!) {
 82→    product(id: $id) {
 83→      id
 84→      title
 85→      handle
 86→      tags
 87→      status
 88→      featuredImage { url }
 89→      priceRangeV2 {
 90→        minVariantPrice { amount }
 91→        maxVariantPrice { amount }
 92→      }
 93→      collections(first: 20) {
 94→        nodes { id }
 95→      }
 96→    }
 97→  }
 98→` as const;
 99→
100→// ─── Helpers ──────────────────────────────────────────────────────────────────
101→
102→function normalizeTag(tag: string): string {
103→  return tag.trim().toLowerCase().replace(/\s+/g, "-");
104→}
105→
106→function buildUpsertPayload(
107→  shop: string,
108→  product: ShopifyProductNode,
109→  isActive: boolean
110→) {
111→  const normalizedTags = product.tags.map(normalizeTag);
112→  const collectionGids = product.collections.nodes.map((c) => c.id);
113→
114→  const create = {
115→    shop,
116→    productGid: product.id,
117→    title: product.title,
118→    handle: product.handle,
119→    imageUrl: product.featuredImage?.url ?? null,
120→    tags: JSON.stringify(normalizedTags),
121→    collections: JSON.stringify(collectionGids),
122→    priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
123→    priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
124→    status: isActive ? ("active" as const) : ("archived" as const),
125→    syncedAt: new Date(),
126→  };
127→
128→  const update = {
129→    title: product.title,
130→    handle: product.handle,
131→    imageUrl: product.featuredImage?.url ?? null,
132→    tags: JSON.stringify(normalizedTags),
133→    collections: JSON.stringify(collectionGids),
134→    priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
135→    priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
136→    status: isActive ? ("active" as const) : ("archived" as const),
137→    syncedAt: new Date(),
138→  };
139→
140→  return { create, update };
141→}
142→
143→async function fetchProductsPage(
144→  admin: { graphql: AdminGraphql },
145→  cursor: string | null
146→): Promise<ShopifyProductsData["products"]> {
147→  const response = await admin.graphql(PRODUCTS_QUERY, {
148→    variables: { first: 50, after: cursor },
149→  });
150→
151→  const json = (await response.json()) as { data: ShopifyProductsData };
152→
153→  if (!json.data?.products) {
154→    throw new Error("Shopify GraphQL returned unexpected shape for products query");
155→  }
156→
157→  return json.data.products;
158→}
