160→// ─── Public API ───────────────────────────────────────────────────────────────
161→
162→/**
163→ * Full catalog sync. Paginates through all Shopify products (50 per page),
164→ * upserts active products, soft-deletes archived/draft ones, and then marks
165→ * any ProductMapping records NOT seen in this sync run as "archived"
166→ * (product was deleted from Shopify without a webhook firing).
167→ *
168→ * Returns { synced, archived } counts.
169→ */
170→export async function syncAllProducts(
171→  shop: string,
172→  admin: { graphql: AdminGraphql }
173→): Promise<{ synced: number; archived: number }> {
174→  let cursor: string | null = null;
175→  let hasMore = true;
176→  let synced = 0;
177→  let archivedDuringSync = 0;
178→
179→  // Track every GID seen during this sync so we can archive any that went missing
180→  const seenGids = new Set<string>();
181→
182→  while (hasMore) {
183→    let page: ShopifyProductsData["products"];
184→
185→    try {
186→      page = await fetchProductsPage(admin, cursor);
187→    } catch (error) {
188→      const message = error instanceof Error ? error.message : String(error);
189→      throw new Error(`Product sync failed while fetching page: ${message}`);
190→    }
191→
192→    for (const product of page.nodes) {
193→      seenGids.add(product.id);
194→      const isActive = product.status === "ACTIVE";
195→      const { create, update } = buildUpsertPayload(shop, product, isActive);
196→
197→      try {
198→        await db.productMapping.upsert({
199→          where: { shop_productGid: { shop, productGid: product.id } },
200→          create,
201→          update,
202→        });
203→      } catch (error) {
204→        const message = error instanceof Error ? error.message : String(error);
205→        console.error(
206→          `[product-sync] Failed to upsert product ${product.id}: ${message}`
207→        );
208→        // Continue with remaining products — one bad record shouldn't abort the run
209→        continue;
210→      }
211→
212→      if (isActive) {
213→        synced++;
214→      } else {
215→        archivedDuringSync++;
216→      }
217→    }
218→
219→    hasMore = page.pageInfo.hasNextPage;
220→    cursor = page.pageInfo.endCursor;
221→  }
222→
223→  // Soft-delete any ProductMapping records that were NOT seen in this sync.
224→  // These are products that were deleted from Shopify (no webhook fired, or we
225→  // missed it). Law 15: never hard-delete synced data.
226→  let ghostArchived = 0;
227→  if (seenGids.size > 0) {
228→    // Collect all active GIDs for this shop that were NOT in the sync
229→    const activeInDb = await db.productMapping.findMany({
230→      where: { shop, status: "active" },
231→      select: { productGid: true },
232→    });
233→
234→    const missingGids = activeInDb
235→      .map((r) => r.productGid)
236→      .filter((gid) => !seenGids.has(gid));
237→
238→    if (missingGids.length > 0) {
239→      const result = await db.productMapping.updateMany({
240→        where: { shop, productGid: { in: missingGids } },
241→        data: { status: "archived", syncedAt: new Date() },
242→      });
243→      ghostArchived = result.count;
244→    }
245→  } else if (seenGids.size === 0) {
246→    // If zero products came back, the store may be empty — archive everything
247→    // that was previously active rather than leaving stale records.
248→    const result = await db.productMapping.updateMany({
249→      where: { shop, status: "active" },
250→      data: { status: "archived", syncedAt: new Date() },
251→    });
252→    ghostArchived = result.count;
253→  }
254→
255→  return {
256→    synced,
257→    archived: archivedDuringSync + ghostArchived,
258→  };
259→}
