261→/**
262→ * Single-product sync, intended for webhook-triggered updates (PRODUCTS_CREATE
263→ * and PRODUCTS_UPDATE). Queries Shopify for the specific GID and upserts the
264→ * local record. If the product is not ACTIVE it is soft-deleted.
265→ */
266→export async function syncSingleProduct(
267→  shop: string,
268→  admin: { graphql: AdminGraphql },
269→  productGid: string
270→): Promise<void> {
271→  let response: Response;
272→
273→  try {
274→    response = await admin.graphql(SINGLE_PRODUCT_QUERY, {
275→      variables: { id: productGid },
276→    });
277→  } catch (error) {
278→    const message = error instanceof Error ? error.message : String(error);
279→    throw new Error(
280→      `Failed to query Shopify for product ${productGid}: ${message}`
281→    );
282→  }
283→
284→  const json = (await response.json()) as { data: ShopifySingleProductData };
285→
286→  if (!json.data) {
287→    throw new Error(
288→      `Shopify GraphQL returned no data for product ${productGid}`
289→    );
290→  }
291→
292→  const product = json.data.product;
293→
294→  if (!product) {
295→    // Product was deleted from Shopify — soft-delete the local record if it exists
296→    await db.productMapping.updateMany({
297→      where: { shop, productGid },
298→      data: { status: "archived", syncedAt: new Date() },
299→    });
300→    return;
301→  }
302→
303→  const isActive = product.status === "ACTIVE";
304→  const { create, update } = buildUpsertPayload(shop, product, isActive);
305→
306→  await db.productMapping.upsert({
307→    where: { shop_productGid: { shop, productGid: product.id } },
308→    create,
309→    update,
310→  });
311→}
